package com.readict.library.infrastructure.storage;

import com.readict.shared.web.ApiProblem;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.regex.Pattern;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;

/**
 * Private file storage for books. Every key is generated by the server; user input never
 * decides a path. The root directory name must match the active profile so a dev process can
 * never write into the test tree (and vice versa).
 */
@Component
public class BookStorage {
    private static final Pattern KEY = Pattern.compile("[A-Za-z0-9/_.-]{1,300}");
    private final String configured;
    private final String profile;
    private volatile Path canonicalRoot;

    public BookStorage(@Value("${readict.library.storage-root:}") String root, Environment environment) {
        this.configured = root == null ? "" : root;
        String[] active = environment.getActiveProfiles();
        this.profile = active.length == 1 ? active[0] : "invalid";
    }

    public boolean configured() { return !configured.isBlank(); }

    public Path root() {
        Path ready = canonicalRoot;
        if (ready != null) return ready;
        synchronized (this) {
            if (canonicalRoot != null) return canonicalRoot;
            if (!configured()) throw new ApiProblem(503, "STORAGE_NOT_CONFIGURED", "本地存储未配置");
            if (!"dev".equals(profile) && !"test".equals(profile)) {
                throw new ApiProblem(503, "STORAGE_ENVIRONMENT_INVALID", "存储环境不合法");
            }
            String expected = "readict_" + profile;
            try {
                Path path = Path.of(configured).toAbsolutePath().normalize();
                if (!path.getFileName().toString().equals(expected)) {
                    throw new ApiProblem(503, "STORAGE_ENVIRONMENT_INVALID", "存储目录名必须与当前环境一致");
                }
                Files.createDirectories(path);
                if (Files.isSymbolicLink(path)) throw new ApiProblem(503, "STORAGE_PATH_ESCAPE", "存储目录不安全");
                Path real = path.toRealPath();
                if (!real.getFileName().toString().equals(expected)) {
                    throw new ApiProblem(503, "STORAGE_ENVIRONMENT_INVALID", "存储目录名必须与当前环境一致");
                }
                canonicalRoot = real;
                return real;
            } catch (IOException ex) {
                throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "本地存储不可用");
            }
        }
    }

    public record Uploaded(Path path, byte[] sha256, long size) {}

    public Path stagingDir(UUID importId) {
        Path dir = inside(root(), "staging/" + safeId(importId));
        try {
            Files.createDirectories(dir);
            return dir;
        } catch (IOException ex) {
            throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "本地存储不可用");
        }
    }

    /** Streams the upload to a staging file while enforcing the byte limit and hashing. */
    public Uploaded writeUpload(UUID importId, InputStream input, long limit) {
        Path dir = stagingDir(importId);
        Path target = dir.resolve("upload.part");
        MessageDigest digest = newDigest();
        long total = 0;
        try (OutputStream out = Files.newOutputStream(target, StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE)) {
            byte[] buffer = new byte[65536];
            int read;
            while ((read = input.read(buffer)) >= 0) {
                total += read;
                if (total > limit) throw new ApiProblem(413, "UPLOAD_TOO_LARGE", "文件超过 25 MB 上限");
                digest.update(buffer, 0, read);
                out.write(buffer, 0, read);
            }
        } catch (ApiProblem problem) {
            deleteTree(dir);
            throw problem;
        } catch (IOException ex) {
            deleteTree(dir);
            throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "本地存储不可用");
        }
        if (total == 0) {
            deleteTree(dir);
            throw new ApiProblem(422, "EPUB_FILE_TYPE_REQUIRED", "文件为空");
        }
        return new Uploaded(target, digest.digest(), total);
    }

    public Path adoptSource(Path upload, UUID userId, UUID bookId) {
        Path target = sourcePath(userId, bookId);
        try {
            Files.createDirectories(target.getParent());
            Files.deleteIfExists(target);
            Files.move(upload, target, StandardCopyOption.ATOMIC_MOVE);
            deleteIfEmpty(upload.getParent());
            return target;
        } catch (IOException ex) {
            throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "源文件保存失败");
        }
    }

    public Path sourcePath(UUID userId, UUID bookId) {
        return inside(root(), sourceKey(userId, bookId));
    }

    public String sourceKey(UUID userId, UUID bookId) {
        return "users/" + safeId(userId) + "/books/" + safeId(bookId) + "/source.epub";
    }

    public String artifactKey(UUID userId, UUID artifactId, String file) {
        if (file == null || !file.matches("[A-Za-z0-9._-]{1,64}")) {
            throw new ApiProblem(500, "STORAGE_PATH_INVALID", "文件标识不合法");
        }
        return "users/" + safeId(userId) + "/artifacts/" + safeId(artifactId) + "/" + file;
    }

    public Path artifactDir(UUID userId, UUID artifactId) {
        return inside(root(), "users/" + safeId(userId) + "/artifacts/" + safeId(artifactId));
    }

    /** Publishes a fully written artifact directory with a same-volume atomic rename. */
    public Path publishArtifacts(Path stagingOut, UUID userId, UUID artifactId) {
        Path target = artifactDir(userId, artifactId);
        try {
            if (Files.exists(target)) throw new ApiProblem(500, "STORAGE_CONFLICT", "产物目录已存在");
            Files.createDirectories(target.getParent());
            Files.move(stagingOut, target, StandardCopyOption.ATOMIC_MOVE);
            return target;
        } catch (ApiProblem problem) {
            throw problem;
        } catch (IOException ex) {
            throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "产物发布失败");
        }
    }

    /** Resolves a stored key for reading, rejecting traversal, symlinks and escapes. */
    public Path resolve(String key) {
        if (key == null || key.isBlank() || !KEY.matcher(key).matches() || key.contains("..") || key.startsWith("/")) {
            throw new ApiProblem(404, "ARTIFACT_NOT_FOUND", "文件不存在");
        }
        Path root = root();
        Path candidate = root.resolve(key).normalize();
        if (!candidate.startsWith(root) || candidate.equals(root)) {
            throw new ApiProblem(404, "ARTIFACT_NOT_FOUND", "文件不存在");
        }
        try {
            if (!Files.isRegularFile(candidate, LinkOption.NOFOLLOW_LINKS)) {
                throw new ApiProblem(404, "ARTIFACT_NOT_FOUND", "文件不存在");
            }
            Path real = candidate.toRealPath();
            if (!real.startsWith(root)) throw new ApiProblem(404, "ARTIFACT_NOT_FOUND", "文件不存在");
            return real;
        } catch (IOException ex) {
            throw new ApiProblem(404, "ARTIFACT_NOT_FOUND", "文件不存在");
        }
    }

    public void deleteByKey(String key) {
        try { deleteTree(resolve(key)); } catch (ApiProblem ignored) { /* already gone */ }
    }

    public byte[] existsAndDigest(String key) {
        return digestFile(resolve(key));
    }

    public void deleteTree(Path path) {
        if (path == null) return;
        try {
            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) return;
            if (Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS)) {
                try (var children = Files.newDirectoryStream(path)) {
                    for (Path child : children) deleteTree(child);
                }
            }
            Files.deleteIfExists(path);
        } catch (IOException ignored) { /* cleanup is best effort; broken state is reported elsewhere */ }
    }

    public long usableBytes() {
        try { return Files.getFileStore(root()).getUsableSpace(); }
        catch (IOException ex) { throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "本地存储不可用"); }
    }

    public static MessageDigest sha256() { return newDigest(); }

    private static MessageDigest newDigest() {
        try { return MessageDigest.getInstance("SHA-256"); }
        catch (NoSuchAlgorithmException ex) { throw new IllegalStateException("SHA-256 unavailable", ex); }
    }

    public static byte[] digestFile(Path file) {
        MessageDigest digest = newDigest();
        try (InputStream in = Files.newInputStream(file)) {
            byte[] buffer = new byte[65536];
            int read;
            while ((read = in.read(buffer)) >= 0) digest.update(buffer, 0, read);
        } catch (IOException ex) {
            throw new ApiProblem(503, "STORAGE_UNAVAILABLE", "文件读取失败");
        }
        return digest.digest();
    }

    private Path inside(Path root, String relative) {
        Path path = root.resolve(relative).normalize();
        if (!path.startsWith(root)) throw new ApiProblem(500, "STORAGE_PATH_INVALID", "文件路径不合法");
        return path;
    }

    private static String safeId(UUID id) {
        if (id == null) throw new ApiProblem(500, "STORAGE_PATH_INVALID", "文件标识不合法");
        return id.toString();
    }

    private static void deleteIfEmpty(Path dir) {
        if (dir == null) return;
        try (var entries = Files.newDirectoryStream(dir)) {
            if (!entries.iterator().hasNext()) Files.deleteIfExists(dir);
        } catch (IOException ignored) { /* keep the directory */ }
    }
}
